text:
値を返す関数は、引数リストの後ろに**戻り値の型**を書きます。Python は `return` するだけで型を書きませんでしたが、Go は `func add(a, b int) int` のように「何型を返すか」を宣言します。宣言と違う型を返すとコンパイルエラーです。**戻り値がない関数は型を書きません**。`func hello()` のように引数リストで止めます。🔴 「返すなら型を書く・返さないなら書かない」を手に覚えさせましょう。

Python ではこう書いた:

```python
def add(a, b):
    return a + b
```

Go ではこう書く:

```go
func add(a, b int) int {
	return a + b
}

// 戻り値なしなら型を書かない
func hello() {
	fmt.Println("hello")
}
```

sample:
// lesson18 ch02: 戻り値の型を書く
package main

import "fmt"

// 引数リストの後ろの int が「戻り値の型」です
func add(a, b int) int {
	return a + b
}

// 戻り値がない関数は型を書きません
func hello() {
	fmt.Println("hello")
}

func main() {
	total := add(3, 5) // 返ってきた値を変数で受け取る
	fmt.Println(total)
	fmt.Println(add(total, 10)) // 式の中でも使える
	hello()
}

exercise.starter:
package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

// ここに area(w, h int) int を定義する

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Scan()
	fields := strings.Fields(sc.Text())
	w, _ := strconv.Atoi(fields[0])
	h, _ := strconv.Atoi(fields[1])
	// ここから下を書く（area の戻り値を出力する）
	_, _ = w, h
	_ = fmt.Println
}

exercise.answer:
// lesson18 ch02 解答
package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

// 計算結果は出力せずに return で返します。
// 「計算する関数」と「表示する場所」を分けておくと、
// 同じ関数をテストや別の計算に使い回せるからです。
func area(w, h int) int {
	return w * h
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Scan()
	fields := strings.Fields(sc.Text())
	w, _ := strconv.Atoi(fields[0])
	h, _ := strconv.Atoi(fields[1])
	fmt.Println(area(w, h))
}
